def ask(request: Request, query: str = None):
    accept_header = request.headers.get("accept", "")
    if "text/html" in accept_header:
        pass
    if not query:
        pass
    try:
        response: RunResponse = multi_ai.run(query)
        answer = response.content
    except Exception as e:
        pass

